13	/**
14	 * Runs after {@link EnsureHouseholdUnique} has allowed the request: when the new owner shares a
15	 * household with one or more existing owners (same lastName and address, compared the same way as
16	 * {@link EnsureHouseholdUnique}), it assigns them all the same {@code householdId} — a stable
17	 * identifier derived deterministically from the normalized lastName and address, so every member of
18	 * the household resolves to the same value regardless of creation order. Existing members that
19	 * predate the household are back-filled so both sides carry the shared id. An owner with no household
20	 * peer keeps a null {@code householdId}. It also records {@code householdSize} — the number of owners
21	 * that share the household after this create (the existing peers plus this new owner).
22	 */
23	public class AssignHouseholdId {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String lastName = normalize(owner.getLastName());
27	        String address = OwnerAddress.normalize(owner.getAddress());
28	        List<Owner> household = new ArrayList<>();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (lastName.equals(normalize(existing.getLastName()))
31	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
32	                household.add(existing);
33	            }
34	        }
35	        // Record the household size after this create: the existing peers plus this new owner.
36	        owner.setHouseholdSize(household.size() + 1);
37	        if (household.isEmpty()) {
38	            return; // no peer at this lastName + address, so no shared household
39	        }
40	        String householdId = deriveHouseholdId(lastName, address);
41	        owner.setHouseholdId(householdId);
42	        for (Owner existing : household) {
43	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
44	                existing.setHouseholdId(householdId);
45	                ownerRepository.save(existing);
46	            }
47	        }
48	    }
49	
50	    /** {@code H-} plus the first 12 upper-case hex chars of SHA-256(lastName + '|' + address). */
51	    private static String deriveHouseholdId(String lastName, String address) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest((lastName + '|' + address).getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder("H-");
56	            for (int i = 0; i < 6; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	    }
65	
66	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
67	    private static String normalize(String value) {
68	        if (value == null) {
69	            return "";
70	        }
71	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
72	    }
73	}
